'use strict';
// Mechanics pass informed by the reference's formation, behavior and ability-draft loop.
const TECHNIQUES={
 seismic:{n:'Earthshatter',group:'front',icon:'◇',cd:13,d:'Slam nearby enemies for 120% attack × ability power and stun for 0.8s. +20% damage per rank.',cast(S,u,r){const es=enemiesOf(S,u).filter(e=>dist(u,e)<125);if(!es.length)return false;for(const e of es){hit(S,u,e,u.atk*u.ap*(1.2+.2*(r-1)),{ab:1});stun(S,u,e,.8)}fx(S,{k:'ring',x:u.x,y:u.y,r0:12,r1:125,c:'#d8b676',fill:1,ttl:.6});shake(S,.2);return true}},
 aegis:{n:'Guardian’s Oath',group:'front',icon:'⬡',cd:15,d:'Shield the weakest nearby ally for 22% of your health and taunt enemies around them for 2s. +5% shield per rank.',cast(S,u,r){const ally=alliesOf(S,u).filter(v=>!v.summon&&dist(v,u)<240).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(!ally||ally.hp/ally.maxHp>.85)return false;shield(S,u,ally,u.maxHp*(.22+.05*(r-1)),5);enemiesOf(S,u).filter(v=>dist(v,ally)<150).forEach(v=>{v.s.taunt=2;v.s.tauntBy=u;v.target=u});fx(S,{k:'dome',u:ally,c:'#8edacb',ttl:.8});return true}},
 challenge:{n:'Iron Challenge',group:'front',icon:'♜',cd:12,d:'Interrupt the nearest enemy caster within 240 range: 150% attack damage and 2s silence. +25% damage per rank.',cast(S,u,r){const e=enemiesOf(S,u).filter(v=>dist(u,v)<240).sort((a,b)=>(b.animCast>0?1000:0)+(b.line==='back'?100:0)-dist(u,b)-((a.animCast>0?1000:0)+(a.line==='back'?100:0)-dist(u,a)))[0];if(!e)return false;hit(S,u,e,u.atk*(1.5+.25*(r-1)),{ab:1});silence(S,u,e,2);e.channel=null;fx(S,{k:'beam',x1:u.x,y1:u.y,x2:e.x,y2:e.y,c:'#f1c78a',ttl:.45});return true}},
 frost:{n:'Winter’s Reach',group:'back',icon:'❄',cd:14,d:'Create a slowing field for 4s at your target. Deals 35% attack × ability power each second. +10% damage per rank.',cast(S,u,r){const e=u.target;if(!e||dist(u,e)>330)return false;S.zones.push({x:e.x,y:e.y,r:95,t:4,ttl:4,dps:u.atk*u.ap*(.35+.1*(r-1)),src:u,team:u.team,hue:190,slow:1});fx(S,{k:'ring',x:e.x,y:e.y,r0:0,r1:95,c:'#91dcf3',ttl:.7});return true}},
 bloom:{n:'Moonlit Renewal',group:'back',icon:'☽',cd:13,d:'Heal the weakest ally within 280 range for 240% attack × ability power and cleanse poison. +40% healing per rank.',cast(S,u,r){const a=alliesOf(S,u).filter(v=>!v.summon&&dist(u,v)<280&&v.hp/v.maxHp<.8).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(!a)return false;heal(S,u,a,u.atk*u.ap*(2.4+.4*(r-1)));a.s.poison=0;fx(S,{k:'beam',x1:u.x,y1:u.y,x2:a.x,y2:a.y,c:'#a7e8b8',ttl:.5});return true}},
 rupture:{n:'Astral Rupture',group:'back',icon:'✧',cd:15,d:'Blast your target and nearby enemies for 100% attack × ability power; silence for 1.2s. +20% damage per rank.',cast(S,u,r){const e=u.target;if(!e||dist(u,e)>330)return false;enemiesOf(S,u).filter(v=>dist(e,v)<85).forEach(v=>{hit(S,u,v,u.atk*u.ap*(1+.2*(r-1)),{ab:1});silence(S,u,v,1.2);v.channel=null});fx(S,{k:'pillar',x:e.x,y:e.y,c:'#c6a3ff',ttl:.7,w:22});return true}},
 pounce:{n:'Predator’s Step',group:'flank',icon:'✦',cd:13,d:'Dash to an exposed backliner within 330 range. Strike for 160% attack × ability power. +25% damage per rank.',cast(S,u,r){const e=enemiesOf(S,u).filter(v=>!v.summon&&dist(u,v)<330).sort((a,b)=>(a.line==='back'?0:500)+a.hp/a.maxHp*100-((b.line==='back'?0:500)+b.hp/b.maxHp*100))[0];if(!e)return false;dash(u,e,450,()=>hit(S,u,e,u.atk*u.ap*(1.6+.25*(r-1)),{ab:1}));return true}},
 cyclone:{n:'Rending Cyclone',group:'flank',icon:'✺',cd:16,d:'Channel for 2.4s: nearby foes take 85% attack per second. Stuns and silence interrupt it. +15% damage per rank.',cast(S,u,r){if(!enemiesOf(S,u).some(e=>dist(u,e)<105))return false;u.channel={key:'cyclone',remaining:2.4,rank:r};return true}},
 siphon:{n:'Crimson Fang',group:'flank',icon:'◈',cd:12,d:'Bite a nearby enemy for 160% attack and heal for half the damage dealt. +25% damage per rank.',cast(S,u,r){const e=u.target;if(!e||dist(u,e)>105)return false;const hp=e.hp;hit(S,u,e,u.atk*(1.6+.25*(r-1)),{ab:1});heal(S,u,u,Math.max(0,hp-e.hp)*.5);fx(S,{k:'crescent',x:e.x,y:e.y,r:35,a:0,c:'#e79494',ttl:.45});return true}}
};
function techniquePoints(b){return Math.max(0,Math.min(6,Math.floor((b.lvl-3)/4)+1)-Object.values(b.techniques||{}).reduce((s,n)=>s+n,0))}
function techniquePool(b){return Object.keys(TECHNIQUES).filter(k=>TECHNIQUES[k].group===ROLE_LINE[roleOf(b)])}
function learnTechnique(b,k){if(!b||!techniquePool(b).includes(k)||techniquePoints(b)<=0||(b.techniques?.[k]||0)>=3)return false;const known=Object.keys(b.techniques||{});if(known.length>=2&&!known.includes(k))return false;b.techniques={...b.techniques,[k]:(b.techniques?.[k]||0)+1};return true}
// Rivals and drafted beasts spend the same level-gated points as the player.
function autoTechniques(b){const pool=techniquePool(b),order=roleOf(b)==='Support'?['bloom','frost']:pool;let guard=0;while(techniquePoints(b)>0&&guard++<6){const known=Object.keys(b.techniques||{}),options=order.filter(k=>known.includes(k)||known.length<2).filter(k=>(b.techniques?.[k]||0)<3).sort((a,z)=>(b.techniques?.[a]||0)-(b.techniques?.[z]||0));if(!options.length||!learnTechnique(b,options[0]))break}}
const techniqueGenBeast=genBeast;genBeast=function(...args){const b=techniqueGenBeast(...args);if(b.clubId!=='P')autoTechniques(b);return b};
const techniqueLoad=load;load=function(){const g=techniqueLoad();if(g)Object.values(g.beasts).filter(b=>b.clubId!=='P').forEach(autoTechniques);return g};
const techniqueRecord=recordMatch;recordMatch=function(...args){const rows=techniqueRecord(...args);for(const r of rows){const b=G.beasts[r.bid];if(b&&b.clubId!=='P')autoTechniques(b)}return rows};
// Preserve the founding cast's core and include its first support in five-a-side.
const foundingGame=newGame;newGame=function(...args){foundingGame(...args);const list=G.clubs.P.roster.map(id=>G.beasts[id]),front=list.find(b=>ROLE_LINE[roleOf(b)]==='front'),support=list.find(b=>roleOf(b)==='Support'),selected=[list[0],front,support,...list].filter(Boolean).filter((b,i,a)=>a.findIndex(v=>v.id===b.id)===i).slice(0,5);G.lineups[5]=selected.map(b=>b.id)};
function techniqueHtml(b,edit){const points=techniquePoints(b),known=Object.keys(b.techniques||{});return `<section class="technique-section"><div class="row between"><h3>Combat techniques</h3><span class="lbl gold">${points} training ${points===1?'point':'points'}</span></div><p class="note">A new point at levels 3, 7, 11, 15, 19, and 23. Learn two techniques and raise them to rank III. These are additional actions your beast uses in the arena.</p><div class="path-grid">${techniquePool(b).map(k=>{const t=TECHNIQUES[k],r=b.techniques?.[k]||0,locked=known.length>=2&&!r;return `<article class="path-card ${r?'active':''}"><div class="row between"><span class="lbl gold">${t.icon} ${r?'Equipped':'Learnable'}</span><span class="note">${t.cd}s cooldown</span></div><h3>${t.n}${r?' '+['','I','II','III'][r]:''}</h3>${gems(r)}<p>${t.d}</p>${edit?`<button class="btn ${r?'':'pri'} sm" data-act="technique" data-id="${b.id}" data-k="${k}" ${!points||r>=3||locked?'disabled':''}>${r>=3?'Mastered':locked?'Two techniques equipped':r?'Upgrade · 1 point':'Learn · 1 point'}</button>`:''}${edit&&r?`<label class="note">Cast timing <select data-chg="techTiming" data-id="${b.id}" data-k="${k}" aria-label="${t.n} cast timing">${[['auto','Whenever useful'],['clutch','Only in danger'],['off','Hold this technique']].map(([v,n])=>`<option value="${v}" ${(b.techTiming?.[k]||'auto')===v?'selected':''}>${n}</option>`).join('')}</select></label>`:''}</article>`}).join('')}</div></section>`}
const powerHtml=upgradesHtml;upgradesHtml=function(b,edit){return techniqueHtml(b,edit)+powerHtml(b,edit)};
const techniquesPanel=techniqueHtml;techniqueHtml=function(b,edit){return techniquesPanel(b,edit)+(edit&&Object.keys(b.techniques||{}).length?`<div class="row" style="margin-top:-12px;margin-bottom:24px"><button class="btn sm" data-act="resetTechniques" data-id="${b.id}" ${G.gold<50?'disabled':''}>Reset techniques · 50 gold</button><span class="note">Refund all technique points and choose a new pair.</span></div>`:'')};
ACT.resetTechniques=d=>{const b=G?.beasts[d.id];if(!b||b.clubId!=='P'||UI.mode==='battle'||G.gold<50||!Object.keys(b.techniques||{}).length)return;G.gold-=50;b.techniques={};b.techTiming={};ledger(`${b.name}: retrained techniques`,-50);save();render();toast('Technique points refunded. Choose a new fighting style.')};
const academyWithChoices=viewAcademy;viewAcademy=function(){const count=G.clubs.P.roster.reduce((s,id)=>s+(G.beasts[id].rolls||0)+techniquePoints(G.beasts[id]),0);return academyWithChoices().replace('<div class="section-heading">',`<section class="panel row between"><div><h3>A keeper’s helping hand</h3><p class="note" style="margin:6px 0">${count} free development choices await. Let the keepers choose role-fitting powers and techniques for your roster.</p></div><button class="btn sm" data-act="keeperTrain" ${count?'':'disabled'}>Let the keepers choose</button></section><div class="section-heading">`)};
ACT.keeperTrain=()=>{if(!G||UI.mode!=='hub')return;G.clubs.P.roster.forEach(id=>{const b=G.beasts[id];autoPick(b);autoTechniques(b)});save();render();toast('Your keepers developed the roster’s powers and techniques.');playCue('upgrade')};
const originalFieldGuide=modalGuide;modalGuide=function(){return originalFieldGuide()+`<section class="behavior-panel"><h3>Your new tools</h3><p class="note">Combat techniques unlock at levels 3, 7, 11, 15, 19, and 23. Equip two, raise each to rank III, and choose when they cast. Silence and stuns interrupt Rending Cyclone. Reset techniques from Skills to try another pair.</p><p class="note">The Academy offers club facilities, three specialization paths, and keeper-assisted training. Formation tiles set the opening position; opening duration delays engagement until an enemy enters attack range. Save different formations for 2v2, 3v3, and 5v5.</p><p class="note">Posture and teamwork appear in each beast’s Tactics tab. Cautious beasts retreat below 40% health and hold offensive dives. Close teamwork protects threatened backliners. Tab moves keyboard focus; Space pauses when focus is outside a control, and 1 / 2 / 4 set battle speed.</p></section>`};
ACT.technique=d=>{const b=G?.beasts[d.id];if(!b||b.clubId!=='P'||UI.mode==='battle'||!learnTechnique(b,d.k))return;save();render();toast(`${b.name} learned ${TECHNIQUES[d.k].n} ${['','I','II','III'][b.techniques[d.k]]}.`);playCue('upgrade')};
TAC_OPTS.ability.push(['disabled','Hold all abilities']);TAC_HELP.ability.disabled='Use basic attacks only. Signature and learned techniques are held.';
const previousGate=gate;gate=function(S,u){return u.tac.ability==='disabled'?false:previousGate(S,u)};
const PERSONALITIES={stoic:{n:'Stoic',d:'Naturally holds the line and stays near allies.',posture:'balanced',teamwork:'close',commitment:'steady'},hunter:{n:'Hunter',d:'Naturally pressures the backline and finishes weak targets.',posture:'aggressive',teamwork:'independent',commitment:'opportunist'},guardian:{n:'Guardian',d:'Naturally stays cautious and watches for threatened allies.',posture:'cautious',teamwork:'close',commitment:'flexible'},bold:{n:'Bold',d:'Naturally pushes forward and sticks to a target.',posture:'aggressive',teamwork:'loose',commitment:'steady'}};
function personality(b){if(!b.personality){const line=ROLE_LINE[roleOf(b)];return line==='front'?'stoic':line==='flank'?'hunter':'guardian'}return b.personality}
function behaviorOf(b){const p=PERSONALITIES[personality(b)]||PERSONALITIES.stoic;return {posture:b.tactics.posture||p.posture,teamwork:b.tactics.teamwork||p.teamwork,commitment:b.tactics.commitment||p.commitment}}
const extraTactics={posture:[['balanced','Balanced'],['cautious','Cautious'],['aggressive','Aggressive']],teamwork:[['close','Close teamwork'],['loose','Loose teamwork'],['independent','Independent']],commitment:[['steady','Stay committed'],['flexible','React to threats'],['opportunist','Finish openings']]};
function behaviorHtml(b){const v=behaviorOf(b);return `<section class="behavior-panel"><h3>Instinct & discipline</h3><p class="note"><b class="gold">${PERSONALITIES[personality(b)].n}.</b> ${PERSONALITIES[personality(b)].d} Your instructions take priority.</p><div class="path-grid">${Object.entries(extraTactics).map(([k,opts])=>`<label class="note">${k[0].toUpperCase()+k.slice(1)}<select data-chg="behavior" data-id="${b.id}" data-k="${k}" aria-label="${k}">${opts.map(([key,n])=>`<option value="${key}" ${v[k]===key?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div><p class="note">Cautious beasts withdraw below 40% health and avoid offensive dives. Close teamwork responds to enemies threatening your backline. Flexible beasts reassess targets faster; opportunists look for enemies below 30% health.</p></section>`}
const previousProfile=modalProfile;modalProfile=function(m){const b=G?.beasts[m.id],html=previousProfile(m);return html+(b?.clubId==='P'&&m.pt==='tactics'?behaviorHtml(b):'')};
document.addEventListener('change',e=>{const d=e.target.dataset,b=G?.beasts[d.id];if(!b||b.clubId!=='P')return;if(d.chg==='techTiming'){b.techTiming={...b.techTiming,[d.k]:e.target.value};save();render()}if(d.chg==='behavior'&&extraTactics[d.k]?.some(([v])=>v===e.target.value)){b.tactics[d.k]=e.target.value;save();render()}});
function formationHtml(){const members=UI.sel.map(id=>G.beasts[id]),sel=members.find(b=>b.id===UI.formBeast)||members[0];const cells=Array.from({length:15},(_,i)=>{const col=i%3,row=Math.floor(i/3),on=members.filter((b,j)=>{const p=b.formation||{col:{back:0,flank:1,front:2}[b.tactics.pos],row:j%5};return p.col===col&&p.row===row});return `<button class="formation-cell ${sel?.formation?.col===col&&sel?.formation?.row===row?'selected':''}" data-act="formPlace" data-col="${col}" data-row="${row}" data-occupant="${on[0]?.id||''}" aria-label="Place ${sel?esc(sel.name):'beast'} in ${['back','middle','front'][col]} row ${row+1}">${on.map(b=>`<span class="formation-unit" data-drag-unit="${b.id}">${beastArt(b.sp)}<span>${esc(b.name)}</span></span>`).join('')||'<i>+</i>'}</button>`}).join('');return `<section class="panel formation-panel"><div><div class="lbl gold">The opening matters</div><h3 style="margin:9px 0">Arrange the first contact.</h3><p class="note">Drag a beast onto a tile, or select its name and click a tile. Occupied tiles swap positions. Formation holds for your opening duration, unless a beast is threatened.</p><div class="row" style="gap:6px">${members.map(b=>`<button class="btn sm ${sel?.id===b.id?'pri':''}" data-act="formSelect" data-id="${b.id}" data-drag-unit="${b.id}">${esc(b.name)}</button>`).join('')}</div><label class="note" style="display:block;margin-top:18px">Opening duration <select data-chg="opening" aria-label="Opening duration">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${(G.opening??2)===n?'selected':''}>${n}s${n===0?' · Engage immediately':''}</option>`).join('')}</select></label><div class="row" style="margin-top:15px"><button class="btn sm" data-act="formSave">Save formation</button><button class="btn sm" data-act="formLoad" ${G.savedFormation?.[UI.ctx.fmt]?'':'disabled'}>Restore formation</button></div></div><div><div class="formation-labels"><span>BACK</span><span>MIDDLE</span><span>FRONT →</span></div><div class="formation-board">${cells}</div></div></section>`}
const previousPrematch=viewPrematch;viewPrematch=function(){let html=previousPrematch();const n=UI.sel.map(id=>G.beasts[id]).reduce((s,b)=>s+(b.rolls||0)+techniquePoints(b),0);html=html.replace('<div class="grid2">',`${formationHtml()}${n?`<div class="prep-alert"><span>✧ <b>${n} development choices</b> are waiting across this lineup.</span><span>Open a beast’s Skills tab before committing.</span></div>`:''}<div class="grid2">`);return html};
function initialFormation(b,index){return b.formation||{col:{back:0,flank:1,front:2}[b.tactics.pos]??1,row:index%5}}
ACT.formSelect=d=>{if(UI.sel.includes(d.id)){UI.formBeast=d.id;render()}};
function moveFormation(id,col,row){
 if(UI.mode!=='prematch'||!UI.sel.includes(id)||!Number.isInteger(col)||col<0||col>2||!Number.isInteger(row)||row<0||row>4)return false;
 const list=UI.sel.map(id=>G.beasts[id]),b=G.beasts[id],old=initialFormation(b,list.indexOf(b));
 const other=list.find((o,i)=>o!==b&&initialFormation(o,i).col===col&&initialFormation(o,i).row===row);
 if(other){other.formation={...old};other.tactics.pos=['back','flank','front'][old.col]}
 b.formation={col,row};b.tactics.pos=['back','flank','front'][col];
 if(UI.ctx&&!UI.ctx.draft)G.lineups[UI.ctx.fmt]=UI.sel.slice();
 return true;
}
ACT.formPlace=d=>{const id=UI.sel.includes(UI.formBeast)?UI.formBeast:UI.sel[0];if(moveFormation(id,Number(d.col),Number(d.row))){save();render()}};
ACT.formSave=()=>{G.savedFormation=G.savedFormation||{};G.savedFormation[UI.ctx.fmt]=UI.sel.map((id,i)=>({id,p:{...initialFormation(G.beasts[id],i)}}));save();render();toast('Formation saved for this bout size.')};
ACT.formLoad=()=>{const saved=G.savedFormation?.[UI.ctx.fmt];if(!saved)return;saved.forEach(({id,p})=>{if(UI.sel.includes(id)&&G.beasts[id]){G.beasts[id].formation={...p};G.beasts[id].tactics.pos=['back','flank','front'][p.col]}});save();render();toast('Saved positions restored for available beasts.')};
document.addEventListener('change',e=>{if(e.target.dataset.chg==='opening'){G.opening=clamp(Number(e.target.value),0,5);save()}});
const previousCreateSim=createSim;createSim=function(A,B,opts={}){[...A,...B].filter(b=>b.clubId!=='P').forEach(autoTechniques);const S=previousCreateSim(A,B,opts);for(const u of S.units){const b=[...A,...B].find(b=>b.id===u.bid);if(!b)continue;u.behavior=behaviorOf(b);u.techniques=Object.entries(b.techniques||{}).filter(([k])=>TECHNIQUES[k]).map(([k,rank])=>({k,rank,cd:3,mode:b.techTiming?.[k]||'auto'}));u.opening=u.team===0?(G?.opening??2):1;u.techStats={casts:0,interrupts:0};const f=b.formation;if(f&&Number.isInteger(f.col)&&Number.isInteger(f.row)&&f.col>=0&&f.col<3&&f.row>=0&&f.row<5){const offset=[365,260,150][f.col];u.x=CX+(u.team?-1:1)*-offset;u.y=CY+(f.row-2)*100;clampArena(u);u.ax=u.x;u.ay=u.y}if(u.behavior.posture==='cautious'){u.tac.retreatAt=Math.max(40,u.tac.retreatAt||0);u.tac.kite=true}if(u.behavior.posture==='aggressive'&&u.tac.stance==='hold')u.tac.stance='advance'}return S};
const previousPickTarget=pickTarget;pickTarget=function(S,u){if(u.behavior&&u.s.taunt<=0&&u.s.confuse<=0){const enemies=enemiesOf(S,u);if(u.behavior.teamwork==='close'){const danger=enemies.filter(e=>alliesOf(S,u).some(a=>a!==u&&!a.summon&&a.line==='back'&&dist(a,e)<115&&e.target===a)).sort((a,b)=>dist(u,a)-dist(u,b))[0];if(danger&&dist(u,danger)<330)return danger}if(u.behavior.commitment==='opportunist'){const weak=enemies.filter(e=>!e.summon&&e.hp/e.maxHp<.3&&dist(u,e)<260).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(weak)return weak}}return previousPickTarget(S,u)};
const DIVE_ABILITIES=new Set(['gore','venom','skystrike','stonedive','vanish','foxfire','maul','antlerrush']);
const behaviorGate=gate;gate=function(S,u){if(u.behavior?.posture==='cautious'&&DIVE_ABILITIES.has(u.ab))return false;return behaviorGate(S,u)};
const previousThink=think;think=function(S,u,dt){if(u.channel&&u.s.stun<=0&&u.s.silence<=0){u.atkT=Math.max(0,u.atkT-dt);u.cdT=Math.max(0,u.cdT-dt);return}if(S.t<(u.opening||0)&&u.s.taunt<=0&&u.s.confuse<=0){const n=nearestEnemy(S,u);if(!n||dist(u,n)>u.range+u.r+n.r){u.target=pickTarget(S,u);return}}previousThink(S,u,dt);if(u.behavior?.commitment==='flexible')u.retT=Math.min(u.retT,.3)};
const previousStep=step;step=function(S,dt){if(S.done)return;for(const u of S.units){if(!u.alive||u.summon)continue;if(u.channel){if(u.s.stun>0||u.s.silence>0){u.channel=null;u.techStats.interrupts++;fx(S,{k:'txt',x:u.x,y:u.y-50,s:'INTERRUPTED',c:'#d8b3f2',z:12,ttl:.9})}else{const ch=u.channel;ch.remaining-=dt;enemiesOf(S,u).filter(e=>dist(u,e)<105).forEach(e=>hit(S,u,e,u.atk*(.85+.15*(ch.rank-1))*dt,{ab:1,dot:1}));if(!S.headless&&Math.floor(S.t*10)!==u.lastSpin){u.lastSpin=Math.floor(S.t*10);fx(S,{k:'crescent',x:u.x,y:u.y,r:75,a:S.t*14,c:'#d9ad81',ttl:.17})}if(ch.remaining<=0)u.channel=null}}
 for(const tech of u.techniques||[]){tech.cd=Math.max(0,tech.cd-dt);if(tech.cd>0||tech.mode==='off'||u.tac.ability==='disabled'||u.s.stun>0||u.s.silence>0||u.s.confuse>0||u.s.stealth>0||u.dash||u.channel||u.strike||u.castLock>0||S.t<(u.opening||0))continue;if(tech.mode==='clutch'&&!alliesOf(S,u).some(v=>v.hp/v.maxHp<.45))continue;if(tech.k==='pounce'&&u.behavior?.posture==='cautious')continue;const t=TECHNIQUES[tech.k];if(t.cast(S,u,tech.rank)){tech.cd=t.cd*(u.cd/SPECIES[u.sp].cd);u.animCast=.45;u.castLock=.28;u.vx=u.vy=0;u.techStats.casts++;fx(S,{k:'txt',x:u.x,y:u.y-45,s:t.n,c:'#d1bce9',z:12,ttl:1.2});if(!S.headless)playCue('cast');break}else tech.cd=.4}
 }previousStep(S,dt)};
const previousViewLevelUp=viewLevelUp;viewLevelUp=function(){const b=G.beasts[UI.lvq[0]];return previousViewLevelUp()+(b?`<section class="panel" style="margin-top:20px">${techniqueHtml(b,true)}</section>`:'')};
const previousResult=viewResult;viewResult=function(){const html=previousResult(),R=UI.result,rows=R.rows.filter(r=>r.team===0);const heal=rows.reduce((s,r)=>s+r.st.heal,0),cc=rows.reduce((s,r)=>s+r.st.cc,0),picks=G.clubs.P.roster.map(id=>G.beasts[id]).reduce((s,b)=>s+techniquePoints(b),0);return html+`<section class="panel coach-report" style="margin-top:20px"><span class="lbl gold">Keeper’s debrief</span><h3 style="margin-top:9px">Make the next bout yours.</h3><div class="path-grid"><p>${heal<50?'Your lineup produced little healing. A support beast or Moonlit Renewal can sustain the front line.':'Your healing supported the team. Use bodyguard orders to keep those healers alive.'}</p><p>${cc<3?'Control was scarce. Earthshatter, Winter’s Reach, or Astral Rupture can stop enemies dictating the fight.':'Your team applied crowd control. Pair it with concentrated damage to finish disabled enemies.'}</p><p>${picks?`${picks} unspent technique points remain in the menagerie. Develop your beasts in the Academy.`:'Review your starting formation and the beasts who fell first. Cautious posture and close teamwork help protect vulnerable allies.'}</p></div></section>`};

document.addEventListener('change',e=>{const d=e.target.dataset,b=G?.beasts[d.id];if(d.chg==='tac'&&d.k==='pos'&&b?.formation){b.formation.col={back:0,flank:1,front:2}[e.target.value];save();render()}});
